toolScript:
(() => {
  const PROFILES = {
    ps5_original: 667,
    ps5_slim: 848,
    ps5_pro: 1890,
    xbox_series_x: 802,
    xbox_series_s: 364,
    xbox_series_s_1tb: 802,
    expansion_1tb: 931,
    expansion_2tb: 1862,
    expansion_4tb: 3724,
  };

  const PRESETS = [
    { title: 'Grand Theft Auto VI (Est.)', sizeGb: 175 },
    { title: 'Call of Duty: Warzone / MW3', sizeGb: 200 },
    { title: "Marvel's Spider-Man 2", sizeGb: 98 },
    { title: "Baldur's Gate 3", sizeGb: 140 },
    { title: 'Star Wars Jedi: Survivor', sizeGb: 150 },
    { title: 'Final Fantasy VII Rebirth', sizeGb: 145 },
    { title: 'Cyberpunk 2077: Phantom Liberty', sizeGb: 70 },
    { title: 'NBA 2K25', sizeGb: 150 },
  ];

  let presetIdx = 0;
  let games = [
    { id: '1', title: 'Open World RPG', sizeGb: 120 },
    { id: '2', title: 'Multiplayer Shooter', sizeGb: 95 },
    { id: '3', title: 'Racing Simulator', sizeGb: 80 },
    { id: '4', title: 'Sports Game', sizeGb: 65 },
  ];

  const platformSelect = document.getElementById('csp-platform-select');
  const customCapacityRow = document.getElementById('csp-custom-capacity-row');
  const customCapacityInput = document.getElementById('csp-custom-capacity');
  const newGameInput = document.getElementById('csp-new-game-size');
  const gamesListEl = document.getElementById('csp-games-list');
  const addGameBtn = document.getElementById('csp-add-game-btn');
  const addPresetBtn = document.getElementById('csp-add-preset-btn');
  const speedSelect = document.getElementById('csp-speed-select');
  const downloadTimeEl = document.getElementById('csp-download-time-val');
  const barInstalled = document.getElementById('bar-installed');
  const barNew = document.getElementById('bar-new');
  const barFree = document.getElementById('bar-free');
  const statInstalled = document.getElementById('stat-installed-gb');
  const statNew = document.getElementById('stat-new-gb');
  const statFree = document.getElementById('stat-free-gb');
  const statusCard = document.getElementById('csp-status-card');
  const statusTitle = document.getElementById('csp-status-title');
  const statusDesc = document.getElementById('csp-status-desc');
  const suggestionsCard = document.getElementById('csp-suggestions-card');
  const suggestionsList = document.getElementById('csp-suggestions-list');

  function getCapacity() {
    const val = platformSelect.value;
    if (val === 'custom') {
      return parseFloat(customCapacityInput.value) || 500;
    }
    return PROFILES[val] || 667;
  }

  function updateDownloadTime(sizeGb) {
    const mbps = parseFloat(speedSelect.value) || 100;
    const totalMbits = Math.max(0.1, sizeGb) * 1024 * 8 * 1.075;
    const seconds = Math.round(totalMbits / mbps);
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    if (h > 0) {
      downloadTimeEl.textContent = `${h}h ${m}m`;
    } else if (m > 0) {
      downloadTimeEl.textContent = `${m}m ${s}s`;
    } else {
      downloadTimeEl.textContent = `${s}s`;
    }
  }

  function renderGames() {
    gamesListEl.innerHTML = '';
    games.forEach((game, idx) => {
      const row = document.createElement('div');
      row.className = 'flex items-center gap-2 p-2 rounded-xl bg-slate-50 border border-slate-200';
      row.innerHTML = `
        <input type="text" value="${game.title}" data-idx="${idx}" class="game-title-input flex-1 px-2.5 py-1 text-xs rounded-lg border border-slate-200 bg-white font-medium text-slate-800" />
        <div class="flex items-center gap-1">
          <input type="number" value="${game.sizeGb}" min="1" max="1000" data-idx="${idx}" class="game-size-input w-20 px-2 py-1 text-xs rounded-lg border border-slate-200 bg-white font-mono text-slate-800" />
          <span class="text-xs text-slate-500 font-medium">GB</span>
        </div>
        <button type="button" data-idx="${idx}" class="delete-game-btn p-1 text-slate-400 hover:text-red-600 transition-colors" title="Delete game">
          <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
        </button>
      `;
      gamesListEl.appendChild(row);
    });

    gamesListEl.querySelectorAll('.game-title-input').forEach((input) => {
      input.addEventListener('input', (e) => {
        const i = parseInt(e.target.dataset.idx, 10);
        games[i].title = e.target.value;
      });
    });

    gamesListEl.querySelectorAll('.game-size-input').forEach((input) => {
      input.addEventListener('input', (e) => {
        const i = parseInt(e.target.dataset.idx, 10);
        games[i].sizeGb = parseFloat(e.target.value) || 0;
        update();
      });
    });

    gamesListEl.querySelectorAll('.delete-game-btn').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const btnEl = e.target.closest('button');
        const i = parseInt(btnEl.dataset.idx, 10);
        games.splice(i, 1);
        renderGames();
        update();
      });
    });
  }

  function update() {
    const capacity = getCapacity();
    const newGameSize = parseFloat(newGameInput.value) || 0;
    const installedTotal = games.reduce((acc, g) => acc + (parseFloat(g.sizeGb) || 0), 0);
    const freeBefore = Math.max(0, capacity - installedTotal);
    const fits = freeBefore >= newGameSize;
    const shortfall = fits ? 0 : newGameSize - freeBefore;
    const freeAfter = fits ? freeBefore - newGameSize : 0;

    statInstalled.textContent = installedTotal.toFixed(1);
    statNew.textContent = newGameSize.toFixed(1);
    statFree.textContent = freeBefore.toFixed(1);

    const installedPct = Math.min(100, (installedTotal / capacity) * 100);
    const newPct = Math.min(100 - installedPct, (newGameSize / capacity) * 100);

    barInstalled.style.width = installedPct.toFixed(1) + '%';
    barNew.style.width = newPct.toFixed(1) + '%';

    updateDownloadTime(newGameSize);

    if (fits) {
      statusCard.className = 'p-4 rounded-xl border border-emerald-200 bg-emerald-50 text-emerald-900 space-y-1';
      statusTitle.textContent = 'Storage Fit Confirmed';
      statusDesc.textContent = 'The target game will fit within existing free capacity. You will have approximately ' + freeAfter.toFixed(1) + ' GB remaining.';
      suggestionsCard.classList.add('hidden');
    } else {
      statusCard.className = 'p-4 rounded-xl border border-rose-200 bg-rose-50 text-rose-900 space-y-1';
      statusTitle.textContent = 'Storage Shortfall Detected';
      statusDesc.textContent = 'Insufficient free capacity. You need to free approximately ' + shortfall.toFixed(1) + ' GB before installation.';

      const sorted = [...games].sort((a, b) => b.sizeGb - a.sizeGb);
      const recommended = [];
      let freed = 0;
      for (const g of sorted) {
        if (freed >= shortfall) break;
        recommended.push(g);
        freed += g.sizeGb;
      }

      if (recommended.length > 0) {
        suggestionsCard.classList.remove('hidden');
        suggestionsList.innerHTML = recommended.map((r) => `<li><strong>${r.title}</strong> (${r.sizeGb} GB)</li>`).join('');
      } else {
        suggestionsCard.classList.add('hidden');
      }
    }
  }

  platformSelect.addEventListener('change', () => {
    if (platformSelect.value === 'custom') {
      customCapacityRow.classList.remove('hidden');
    } else {
      customCapacityRow.classList.add('hidden');
    }
    update();
  });

  customCapacityInput.addEventListener('input', update);
  newGameInput.addEventListener('input', update);
  speedSelect.addEventListener('change', () => updateDownloadTime(parseFloat(newGameInput.value) || 0));

  addGameBtn.addEventListener('click', () => {
    games.push({ id: String(Date.now()), title: 'Custom Game Title', sizeGb: 50 });
    renderGames();
    update();
  });

  addPresetBtn.addEventListener('click', () => {
    const preset = PRESETS[presetIdx % PRESETS.length];
    presetIdx++;
    games.push({ id: String(Date.now()), title: preset.title, sizeGb: preset.sizeGb });
    renderGames();
    update();
  });

  renderGames();
  update();
})();
